 void validatesHypitLengths(){QTemporaryDir tmp;QJsonObject h{{"distributionPath",QString(5000,'x')},{"launcher","bin/hypit.mjs"},{"version","0.2.10"}};const auto path=tmp.filePath("config/version-lock.json");QVERIFY(write(path,QJsonDocument(QJsonObject{{"hypit",h}}).toJson()));QVERIFY(!loadAppConfig(path).ok());}
 void bundledConfigWinsOverDeveloperConfig(){QTemporaryDir tmp;const auto executable=tmp.filePath("release/Workbench.app/Contents/MacOS/workbench");QDir().mkpath(QFileInfo(executable).absolutePath());QVERIFY(QFile::copy(QCoreApplication::applicationFilePath(),executable));const auto path=tmp.filePath("release/Workbench.app/Contents/Resources/config/version-lock.json");QVERIFY(write(path,config().replace("../hypit","../../../hypit")));QProcess child;child.start(executable,{"--config-probe"});QVERIFY(child.waitForFinished(3000));const auto result=QJsonDocument::fromJson(child.readAllStandardOutput()).object();QCOMPARE(result["error"].toString(),QString());QCOMPARE(result["config"].toString(),QFileInfo(path).canonicalFilePath());QCOMPARE(result["distribution"].toString(),QFileInfo(tmp.path()).canonicalFilePath()+"/release/hypit");}
 void explicitNodeRecognizesOnlyPinnedOfficialShell(){QTemporaryDir tmp;const auto official=QFINDTESTDATA("../../../hypit/hypit");QVERIFY2(!official.isEmpty(),"Pinned external Hypit shell is needed for this contract test");const auto launcher=tmp.filePath("distribution/hypit"),script=tmp.filePath("distribution/bin/hypit.mjs"),node=tmp.filePath("custom-node"),path=tmp.filePath("repo/config/version-lock.json");QDir().mkpath(QFileInfo(launcher).absolutePath());QVERIFY(QFile::copy(official,launcher));QVERIFY(write(script,"console.log(JSON.stringify({version:'wrong-node'}));\n"));QVERIFY(write(node,"#!/bin/sh\ncase \"$1\" in */bin/hypit.mjs) printf '%s' '{\"version\":\"0.2.10\"}' ;; *) exit 66 ;; esac\n"));QVERIFY(QFile::setPermissions(node,QFile::ReadOwner|QFile::WriteOwner|QFile::ExeOwner));auto object=QJsonDocument::fromJson(config().replace("../hypit","../distribution").replace("bin/hypit.mjs","hypit")).object();object.insert("tools",QJsonObject{{"node",node}});QVERIFY(write(path,QJsonDocument(object).toJson()));const auto loaded=loadAppConfig(path);QVERIFY2(loaded.ok(),qPrintable(loaded.error));QVERIFY(loaded.config.nodeExplicit);const auto invocation=RuntimePaths::hypitInvocation(loaded.config.launcherPath,loaded.config.nodePath,true,{"version","--json"});QVERIFY2(invocation.ok(),qPrintable(invocation.error));QCOMPARE(invocation.program,node);QCOMPARE(QFileInfo(invocation.arguments[0]).canonicalFilePath(),QFileInfo(script).canonicalFilePath());LogWriter log(tmp.filePath("log"));HypitProbe probe;QSignalSpy completed(&probe,&HypitProbe::completed);probe.start(loaded.config,log);QTRY_COMPARE_WITH_TIMEOUT(completed.size(),1,2000);QVERIFY2(completed[0][0].value<ProbeResult>().ok(),qPrintable(completed[0][0].value<ProbeResult>().message));QVERIFY(write(script,"console.log(JSON.stringify({version:'0.2.10'}));\n"));const auto fallbackNode=tmp.filePath("fallback/node");QVERIFY(write(fallbackNode,"#!/usr/bin/python3\nimport json,os,sys\nif sys.argv[1]=='-e': print(os.path.realpath(sys.argv[3]),end='')\nelse: print(json.dumps({'version':'0.2.10'}))\n"));QVERIFY(QFile::setPermissions(fallbackNode,QFile::ReadOwner|QFile::WriteOwner|QFile::ExeOwner));object.remove("tools");QVERIFY(write(path,QJsonDocument(object).toJson()));const auto oldPath=qgetenv("PATH");qputenv("PATH",QFileInfo(fallbackNode).absolutePath().toUtf8());const auto restorePath=qScopeGuard([oldPath]{qputenv("PATH",oldPath);});const auto defaultConfig=loadAppConfig(path);QVERIFY2(defaultConfig.ok(),qPrintable(defaultConfig.error));QVERIFY(!defaultConfig.config.nodeExplicit);const auto direct=RuntimePaths::hypitInvocation(defaultConfig.config.launcherPath,defaultConfig.config.nodePath,false,{"version","--json"});QCOMPARE(direct.program,defaultConfig.config.launcherPath);completed.clear();probe.start(defaultConfig.config,log);QTRY_COMPARE_WITH_TIMEOUT(completed.size(),1,2000);QVERIFY2(completed[0][0].value<ProbeResult>().ok(),qPrintable(completed[0][0].value<ProbeResult>().message));QVERIFY(write(launcher,"#!/bin/sh\nprintf '%s' '{\"version\":\"0.2.10\"}'\n"));const auto custom=RuntimePaths::hypitInvocation(launcher,node,true,{"version","--json"});QVERIFY(!custom.ok());QVERIFY(custom.error.contains("自定义"));}
 void loadedShellLauncherAlsoWorksForStudio(){QTemporaryDir tmp;const auto launcher=tmp.filePath("distribution/hypit"),path=tmp.filePath("repo/config/version-lock.json"),run=tmp.filePath("main.svrun"),runtime=tmp.filePath("hypit.runtime.json");QVERIFY(write(launcher,"#!/bin/sh\nif [ \"$1\" = version ]; then printf '%s' '{\"version\":\"0.2.10\"}'; elif [ \"$1\" = studio ]; then printf '%s\\n' 'Local: http://localhost:5599/'; sleep 1; else exit 65; fi\n"));QVERIFY(QFile::setPermissions(launcher,QFile::ReadOwner|QFile::WriteOwner|QFile::ExeOwner));QVERIFY(write(path,config().replace("../hypit","../distribution").replace("bin/hypit.mjs","hypit")));QVERIFY(write(run,"run"));QVERIFY(write(runtime,"{\"format\":\"hypit.runtime-local@1\",\"endpoints\":{\"media\":{\"use\":\"@hypit/provider-media-local\"}}}"));const auto loaded=loadAppConfig(path);QVERIFY2(loaded.ok(),qPrintable(loaded.error));LogWriter log(tmp.filePath("log"));qvw::controllers::ProjectController controller(loaded.config,log);QSignalSpy initialized(&controller,&qvw::controllers::ProjectController::initialized),preview(&controller,&qvw::controllers::ProjectController::previewRequested);controller.initialize();QTRY_COMPARE_WITH_TIMEOUT(initialized.size(),1,2000);controller.openProject(tmp.path(),run,runtime);QTRY_COMPARE_WITH_TIMEOUT(preview.size(),1,2000);controller.closeProject();}
 void loadedDefaultNodePreservesExecutableShellLauncher(){QTemporaryDir tmp;const auto launcher=tmp.filePath("distribution/hypit"),path=tmp.filePath("repo/config/version-lock.json"),fakeNode=tmp.filePath("fake-tools/node");QVERIFY(write(launcher,"#!/bin/sh\nprintf '%s' '{\"version\":\"0.2.10\"}'\n"));QVERIFY(write(fakeNode,"#!/bin/sh\nexit 65\n"));for(const auto &file:{launcher,fakeNode})QVERIFY(QFile::setPermissions(file,QFile::ReadOwner|QFile::WriteOwner|QFile::ExeOwner));QVERIFY(write(path,config().replace("../hypit","../distribution").replace("bin/hypit.mjs","hypit")));const auto original=qgetenv("PATH");qputenv("PATH",QFileInfo(fakeNode).absolutePath().toUtf8());const auto restore=qScopeGuard([original]{qputenv("PATH",original);});const auto loaded=loadAppConfig(path);QVERIFY2(loaded.ok(),qPrintable(loaded.error));QVERIFY(!loaded.config.nodePath.isEmpty());LogWriter log(tmp.filePath("log"));HypitProbe probe;QSignalSpy completed(&probe,&HypitProbe::completed);probe.start(loaded.config,log);QTRY_COMPARE_WITH_TIMEOUT(completed.size(),1,2000);const auto result=completed[0][0].value<ProbeResult>();QVERIFY2(result.ok(),qPrintable(result.message));}
 void projectConfigPropagatesExplicitNodeToStudio(){QTemporaryDir tmp;const auto node=tmp.filePath("custom-node"),launcher=tmp.filePath("launcher.mjs"),run=tmp.filePath("main.svrun"),runtime=tmp.filePath("hypit.runtime.json");QVERIFY(write(run,"run"));QVERIFY(write(runtime,"{\"format\":\"hypit.runtime-local@1\",\"endpoints\":{\"media\":{\"use\":\"@hypit/provider-media-local\"}}}"));QVERIFY(write(launcher,"#!/bin/sh\nexit 65\n"));QVERIFY(write(node,"#!/bin/sh\nif [ \"$2\" = version ]; then printf '%s' '{\"version\":\"0.2.10\"}'; elif [ \"$2\" = studio ]; then printf '%s\\n' 'Local: http://localhost:5599/'; sleep 1; else exit 66; fi\n"));for(const auto &path:{node,launcher})QVERIFY(QFile::setPermissions(path,QFile::ReadOwner|QFile::WriteOwner|QFile::ExeOwner));AppConfig config;config.nodePath=node;config.launcherPath=launcher;config.distributionPath=tmp.path();config.expectedHypitVersion="0.2.10";LogWriter log(tmp.filePath("log"));qvw::controllers::ProjectController controller(config,log);QSignalSpy initialized(&controller,&qvw::controllers::ProjectController::initialized),preview(&controller,&qvw::controllers::ProjectController::previewRequested);controller.initialize();QTRY_COMPARE_WITH_TIMEOUT(initialized.size(),1,2000);controller.openProject(tmp.path(),run,runtime);QTRY_COMPARE_WITH_TIMEOUT(preview.size(),1,2000);controller.closeProject();}
