 void explicitToolsResolveInChildren(){QTemporaryDir tmp;QJsonObject tools;for(const auto &name:{"node","ffmpeg","ffprobe"}){const auto path=tmp.filePath(QString::fromLatin1(name)+" tool/bin/"+name);QVERIFY(write(path,"#!/bin/sh\nprintf '%s' '{\"located\":true}'\n"));QVERIFY(QFile::setPermissions(path,QFile::ReadOwner|QFile::WriteOwner|QFile::ExeOwner));tools.insert(name,path);}const auto path=tmp.filePath("config/version-lock.json");auto document=QJsonDocument::fromJson(config()).object();document.insert("tools",tools);QVERIFY(write(path,QJsonDocument(document).toJson()));const auto loaded=loadAppConfig(path);QVERIFY2(loaded.ok(),qPrintable(loaded.error));QCOMPARE(loaded.config.nodePath,tools["node"].toString());QCOMPARE(loaded.config.ffmpegPath,tools["ffmpeg"].toString());QCOMPARE(loaded.config.ffprobePath,tools["ffprobe"].toString());for(const auto &value:tools)QVERIFY(loaded.config.processEnvironment.value("PATH").split(':').contains(QFileInfo(value.toString()).absolutePath()));JsonProcess child;child.setEnvironment(loaded.config.processEnvironment);QSignalSpy result(&child,&JsonProcess::result);QVERIFY(child.start("/usr/bin/env",{"node"},tmp.path()));QTRY_COMPARE_WITH_TIMEOUT(result.size(),1,2000);QVERIFY(qvariant_cast<QJsonObject>(result[0][0])["located"].toBool());}
