 void mediaDecodeGetsStandardPath(){QTemporaryDir tmp;const auto probe=tmp.filePath("probe"),decode=tmp.filePath("decode"),movie=tmp.filePath("movie.mp4");QVERIFY(write(movie,"fixture"));QVERIFY(write(probe,"#!/usr/bin/env python3\nprint('{\"streams\":[{\"codec_type\":\"video\",\"codec_name\":\"h264\",\"width\":640,\"height\":360,\"avg_frame_rate\":\"30/1\"}],\"format\":{\"format_name\":\"mp4\",\"duration\":\"2\"}}')\n"));QVERIFY(write(decode,"#!/usr/bin/env python3\nimport sys\nsys.exit(0)\n"));for(const auto &path:{probe,decode})QVERIFY(QFile::setPermissions(path,QFile::ReadOwner|QFile::WriteOwner|QFile::ExeOwner));const auto original=qgetenv("PATH");qputenv("PATH","/missing-tools");const auto restore=qScopeGuard([original]{qputenv("PATH",original);});qvw::services::MediaValidation validation;QSignalSpy validated(&validation,&qvw::services::MediaValidation::validated),failed(&validation,&qvw::services::MediaValidation::failed);const bool started=validation.start(movie,{640,360,60,2,30},probe,decode);QVERIFY(started);QTRY_COMPARE_WITH_TIMEOUT(validated.size(),1,2000);QCOMPARE(failed.size(),0);}
 void studioGetsStandardPath(){QTemporaryDir tmp;const auto launcher=tmp.filePath("launcher"),run=tmp.filePath("main.svrun"),runtime=tmp.filePath("runtime.json");QVERIFY(write(run,"run"));QVERIFY(write(runtime,"{}"));QVERIFY(write(launcher,"#!/usr/bin/env python3\nprint('Local: http://localhost:5599/', flush=True)\n"));QVERIFY(QFile::setPermissions(launcher,QFile::ReadOwner|QFile::WriteOwner|QFile::ExeOwner));const auto original=qgetenv("PATH");qputenv("PATH","/missing-tools");qvw::backend::hypit::StudioProcess studio;QSignalSpy ready(&studio,&qvw::backend::hypit::StudioProcess::ready),failed(&studio,&qvw::backend::hypit::StudioProcess::failed);const bool started=studio.start(launcher,tmp.path(),run,runtime);qputenv("PATH",original);QVERIFY(started);QTRY_COMPARE_WITH_TIMEOUT(ready.size(),1,2000);QCOMPARE(failed.size(),0);}
 void childPathIncludesStandardToolsWithoutChangingParent(){QTemporaryDir tmp;const auto original=qgetenv("PATH");qputenv("PATH","/missing-tools");JsonProcess p;QSignalSpy result(&p,&JsonProcess::result);QVERIFY(p.start("/usr/bin/python3",{"-c","import json,os; print(json.dumps({'path':os.environ['PATH']}))"},tmp.path()));QTRY_COMPARE_WITH_TIMEOUT(result.size(),1,1500);const auto path=qvariant_cast<QJsonObject>(result[0][0])["path"].toString();QCOMPARE(qgetenv("PATH"),QByteArray("/missing-tools"));qputenv("PATH",original);for(const auto &entry:{"/opt/homebrew/bin","/usr/local/bin","/usr/bin","/bin","/usr/sbin","/sbin"})QVERIFY2(path.split(':').contains(entry),qPrintable(path));}
