int main(int argc,char **argv){QCoreApplication app(argc,argv);if(app.arguments().contains("--config-probe")){const auto loaded=loadAppConfig();QFile out;if(!out.open(stdout,QIODevice::WriteOnly))return 2;out.write(QJsonDocument(QJsonObject{{"error",loaded.error},{"config",loaded.config.configFilePath},{"distribution",loaded.config.distributionPath}}).toJson(QJsonDocument::Compact));return loaded.ok()?0:1;}RuntimePathsTest test;return QTest::qExec(&test,argc,argv);}
